function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(98, 100) : int(2, 10);
  const top = size === 'small' && rand() < 0.5 ? 5 : 1000;
  const score = int(2, 2 * top);
  const pairs = int(0, Math.floor(n / 2));
  const nums = [];
  for (let p = 0; p < pairs; p++) {
    const left = int(Math.max(1, score - top), Math.min(top, score - 1));
    nums.push(left, score - left);
  }
  while (nums.length < n) nums.push(int(1, top));
  return [nums];
}
